import { Link } from 'react-router-dom'

interface Props {
  size?: 'sm' | 'md' | 'lg'
  linkable?: boolean
}

// The Clip logo is one vector file, public/logo.svg, generated by scripts/make_logo.py.
// These heights keep the C the same size the header has always shown it (sm 18px, md 25px, lg 35px).
const HEIGHT = { sm: 26, md: 36, lg: 50 } as const

export default function Logo({ size = 'lg', linkable = true }: Props) {
  const content = (
    <img
      src="/logo.svg"
      alt="Clip"
      height={HEIGHT[size]}
      draggable={false}
      style={{ display: 'block', width: 'auto', userSelect: 'none' }}
    />
  )

  if (linkable) {
    return (
      <Link to="/" style={{ textDecoration: 'none', display: 'inline-block' }}>
        {content}
      </Link>
    )
  }

  return content
}
